import 'package:flutter/material.dart';\nimport 'package:path_provider/path_provider.dart';\n\nimport '../../data/models/service_card.dart';\nimport '../../data/repositories/backend_repository.dart';\nimport '../../widgets/loading_state_view.dart';\nimport 'card_pdf_generator.dart';\n\nclass CardsPrintManager extends StatefulWidget {\n  const CardsPrintManager({super.key, required this.repository});\n\n  final BackendRepository repository;\n\n  @override\n  State<CardsPrintManager> createState() => _CardsPrintManagerState();\n}\n\nclass _CardsPrintManagerState extends State<CardsPrintManager> {\n  List<ServiceCard> _allCards = [];\n  List<ServiceCard> _selectedCards = [];\n  bool _isLoading = false;\n  bool _selectAll = false;\n\n  @override\n  void initState() {\n    super.initState();\n    _loadCards();\n  }\n\n  Future<void> _loadCards() async {\n    setState(() => _isLoading = true);\n    try {\n      final cards = await widget.repository.cards();\n      setState(() {\n        _allCards = cards;\n        _isLoading = false;\n      });\n    } catch (e) {\n      setState(() => _isLoading = false);\n      if (mounted) {\n        ScaffoldMessenger.of(context).showSnackBar(\n          SnackBar(content: Text('خطأ في تحميل البطاقات: $e')),\n        );\n      }\n    }\n  }\n\n  void _toggleCardSelection(ServiceCard card) {\n    setState(() {\n      if (_selectedCards.contains(card)) {\n        _selectedCards.remove(card);\n      } else {\n        _selectedCards.add(card);\n      }\n      _updateSelectAllStatus();\n    });\n  }\n\n  void _toggleSelectAll() {\n    setState(() {\n      if (_selectAll) {\n        _selectedCards.clear();\n        _selectAll = false;\n      } else {\n        _selectedCards = List.from(_allCards);\n        _selectAll = true;\n      }\n    });\n  }\n\n  void _updateSelectAllStatus() {\n    _selectAll = _selectedCards.length == _allCards.length;\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('طباعة البطاقات'),\n        actions: [\n          if (_selectedCards.isNotEmpty)\n            PopupMenuButton<String>(\n              onSelected: _handleMenuAction,\n              itemBuilder: (context) => [\n                const PopupMenuItem(\n                  value: 'preview',\n                  child: ListTile(\n                    leading: Icon(Icons.preview),\n                    title: Text('معاينة'),\n                  ),\n                ),\n                const PopupMenuItem(\n                  value: 'print',\n                  child: ListTile(\n                    leading: Icon(Icons.print),\n                    title: Text('طباعة'),\n                  ),\n                ),\n                const PopupMenuItem(\n                  value: 'save',\n                  child: ListTile(\n                    leading: Icon(Icons.save),\n                    title: Text('حفظ PDF'),\n                  ),\n                ),\n                const PopupMenuItem(\n                  value: 'share',\n                  child: ListTile(\n                    leading: Icon(Icons.share),\n                    title: Text('مشاركة'),\n                  ),\n                ),\n              ],\n            ),\n        ],\n      ),\n      body: _isLoading\n          ? const LoadingStateView()\n          : Column(\n              children: [\n                // شريط الأدوات\n                Container(\n                  padding: const EdgeInsets.all(16),\n                  decoration: BoxDecoration(\n                    color: Theme.of(context).colorScheme.surfaceVariant,\n                    borderRadius: const BorderRadius.only(\n                      bottomLeft: Radius.circular(16),\n                      bottomRight: Radius.circular(16),\n                    ),\n                  ),\n                  child: Column(\n                    children: [\n                      Row(\n                        children: [\n                          Checkbox(\n                            value: _selectAll,\n                            onChanged: (_) => _toggleSelectAll(),\n                          ),\n                          const Text('تحديد الكل'),\n                          const Spacer(),\n                          Text(\n                            'تم اختيار ${_selectedCards.length} من ${_allCards.length}',\n                            style: Theme.of(context).textTheme.bodyMedium,\n                          ),\n                        ],\n                      ),\n                      if (_selectedCards.isNotEmpty) ..[\n                        const SizedBox(height: 16),\n                        Row(\n                          children: [\n                            Expanded(\n                              child: OutlinedButton.icon(\n                                onPressed: () => _handleMenuAction('preview'),\n                                icon: const Icon(Icons.preview),\n                                label: const Text('معاينة'),\n                              ),\n                            ),\n                            const SizedBox(width: 8),\n                            Expanded(\n                              child: FilledButton.icon(\n                                onPressed: () => _handleMenuAction('print'),\n                                icon: const Icon(Icons.print),\n                                label: const Text('طباعة'),\n                              ),\n                            ),\n                          ],\n                        ),\n                      ],\n                    ],\n                  ),\n                ),\n                \n                // قائمة البطاقات\n                Expanded(\n                  child: ListView.builder(\n                    padding: const EdgeInsets.all(16),\n                    itemCount: _allCards.length,\n                    itemBuilder: (context, index) {\n                      final card = _allCards[index];\n                      final isSelected = _selectedCards.contains(card);\n                      \n                      return Card(\n                        margin: const EdgeInsets.only(bottom: 12),\n                        child: CheckboxListTile(\n                          value: isSelected,\n                          onChanged: (_) => _toggleCardSelection(card),\n                          title: Text(card.title),\n                          subtitle: Column(\n                            crossAxisAlignment: CrossAxisAlignment.start,\n                            children: [\n                              Text('السعة: ${card.quota} | السعر: ${card.price.toStringAsFixed(2)} ر.س'),\n                              if (card.username != null)\n                                Text('المستخدم: ${card.username}'),\n                              Container(\n                                padding: const EdgeInsets.symmetric(\n                                  horizontal: 8,\n                                  vertical: 4,\n                                ),\n                                decoration: BoxDecoration(\n                                  color: card.status.contains('موقوف')\n                                      ? Colors.red.withOpacity(0.1)\n                                      : Colors.green.withOpacity(0.1),\n                                  borderRadius: BorderRadius.circular(4),\n                                ),\n                                child: Text(\n                                  card.status,\n                                  style: TextStyle(\n                                    color: card.status.contains('موقوف')\n                                        ? Colors.red\n                                        : Colors.green,\n                                    fontSize: 12,\n                                  ),\n                                ),\n                              ),\n                            ],\n                          ),\n                          secondary: CircleAvatar(\n                            child: Text(\n                              card.id.length > 2 \n                                  ? card.id.substring(0, 2)\n                                  : card.id,\n                            ),\n                          ),\n                        ),\n                      );\n                    },\n                  ),\n                ),\n              ],\n            ),\n    );\n  }\n\n  Future<void> _handleMenuAction(String action) async {\n    if (_selectedCards.isEmpty) {\n      ScaffoldMessenger.of(context).showSnackBar(\n        const SnackBar(content: Text('الرجاء اختيار بطاقة واحدة على الأقل')),\n      );\n      return;\n    }\n\n    setState(() => _isLoading = true);\n\n    try {\n      switch (action) {\n        case 'preview':\n          await CardPdfGenerator.previewCards(_selectedCards);\n          break;\n        case 'print':\n          await CardPdfGenerator.printCards(_selectedCards);\n          break;\n        case 'save':\n          final path = await CardPdfGenerator.saveCardsPdf(_selectedCards);\n          if (mounted) {\n            ScaffoldMessenger.of(context).showSnackBar(\n              SnackBar(\n                content: Text('تم حفظ الملف في: $path'),\n                action: SnackBarAction(\n                  label: 'مشاركة',\n                  onPressed: () => CardPdfGenerator.shareCards(_selectedCards),\n                ),\n              ),\n            );\n          }\n          break;\n        case 'share':\n          await CardPdfGenerator.shareCards(_selectedCards);\n          break;\n      }\n    } catch (e) {\n      if (mounted) {\n        ScaffoldMessenger.of(context).showSnackBar(\n          SnackBar(content: Text('خطأ: $e')),\n        );\n      }\n    } finally {\n      setState(() => _isLoading = false);\n    }\n  }\n}\n\n// ودجت لمعاينة البطاقة الفردية\nclass CardPreviewWidget extends StatelessWidget {\n  const CardPreviewWidget({super.key, required this.card});\n\n  final ServiceCard card;\n\n  @override\n  Widget build(BuildContext context) {\n    return Container(\n      width: 300,\n      height: 200,\n      margin: const EdgeInsets.all(8),\n      decoration: BoxDecoration(\n        gradient: const LinearGradient(\n          colors: [Color(0xFF1E3C72), Color(0xFF2A5298)],\n          begin: Alignment.topLeft,\n          end: Alignment.bottomRight,\n        ),\n        borderRadius: BorderRadius.circular(12),\n        boxShadow: [\n          BoxShadow(\n            color: Colors.black.withOpacity(0.1),\n            blurRadius: 8,\n            offset: const Offset(0, 4),\n          ),\n        ],\n      ),\n      child: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            // رأس البطاقة\n            Row(\n              mainAxisAlignment: MainAxisAlignment.spaceBetween,\n              children: [\n                Column(\n                  crossAxisAlignment: CrossAxisAlignment.start,\n                  children: const [\n                    Text(\n                      'NUM',\n                      style: TextStyle(\n                        color: Colors.white,\n                        fontSize: 20,\n                        fontWeight: FontWeight.bold,\n                      ),\n                    ),\n                    Text(\n                      'بطاقة إنترنت',\n                      style: TextStyle(\n                        color: Colors.white70,\n                        fontSize: 12,\n                      ),\n                    ),\n                  ],\n                ),\n                Container(\n                  width: 40,\n                  height: 40,\n                  decoration: const BoxDecoration(\n                    color: Colors.white,\n                    shape: BoxShape.circle,\n                  ),\n                  child: const Icon(\n                    Icons.wifi,\n                    color: Color(0xFF1E3C72),\n                    size: 20,\n                  ),\n                ),\n              ],\n            ),\n            \n            const SizedBox(height: 16),\n            \n            // معلومات البطاقة\n            Container(\n              padding: const EdgeInsets.all(12),\n              decoration: BoxDecoration(\n                color: Colors.white,\n                borderRadius: BorderRadius.circular(8),\n              ),\n              child: Column(\n                children: [\n                  Text(\n                    card.title,\n                    style: const TextStyle(\n                      fontSize: 14,\n                      fontWeight: FontWeight.bold,\n                      color: Color(0xFF1E3C72),\n                    ),\n                  ),\n                  const SizedBox(height: 8),\n                  Row(\n                    mainAxisAlignment: MainAxisAlignment.spaceEvenly,\n                    children: [\n                      Column(\n                        children: [\n                          const Text('السعة', style: TextStyle(fontSize: 10, color: Colors.grey)),\n                          Text(card.quota, style: const TextStyle(fontSize: 12, fontWeight: FontWeight.bold)),\n                        ],\n                      ),\n                      Column(\n                        children: [\n                          const Text('السعر', style: TextStyle(fontSize: 10, color: Colors.grey)),\n                          Text('${card.price.toStringAsFixed(0)} ر.س', style: const TextStyle(fontSize: 12, fontWeight: FontWeight.bold)),\n                        ],\n                      ),\n                    ],\n                  ),\n                ],\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}